import operator
import re
import sys
import threading

_TOKEN_RE = re.compile(r'[A-Z][0-9]+|[A-Z]+|[0-9]+|<>|<=|>=|[-+*/()<>=,:]')
_CELL_RE = re.compile(r'[A-Z][0-9]+')
_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"
_OPS = {
    '=': operator.eq,
    '<>': operator.ne,
    '<': operator.lt,
    '<=': operator.le,
    '>': operator.gt,
    '>=': operator.ge,
}


def _is_err(v):
    return isinstance(v, str)


def _is_cell(tok):
    return _CELL_RE.fullmatch(tok) is not None


def _tokenize(text):
    text = re.sub(r'\s+', '', text)
    tokens = []
    pos = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            raise ValueError(f"bad token at {pos} in {text!r}")
        tokens.append(m.group())
        pos = m.end()
    return tokens


def _expect(t, p, tok):
    if p < len(t) and t[p] == tok:
        return p + 1
    raise ValueError(f"expected {tok!r} at {p}")


def _parse_expr(t, p):
    node, p = _parse_term(t, p)
    while p < len(t) and t[p] in ('+', '-'):
        op = t[p]
        right, p = _parse_term(t, p + 1)
        node = ('bin', op, node, right)
    return node, p


def _parse_term(t, p):
    node, p = _parse_unary(t, p)
    while p < len(t) and t[p] in ('*', '/'):
        op = t[p]
        right, p = _parse_unary(t, p + 1)
        node = ('bin', op, node, right)
    return node, p


def _parse_unary(t, p):
    if p < len(t) and t[p] == '-':
        node, p = _parse_unary(t, p + 1)
        return ('neg', node), p
    return _parse_atom(t, p)


def _parse_atom(t, p):
    if p >= len(t):
        raise ValueError("unexpected end of formula")
    tok = t[p]
    if tok.isdigit():
        return ('num', int(tok)), p + 1
    if tok == '(':
        node, p = _parse_expr(t, p + 1)
        return node, _expect(t, p, ')')
    if _is_cell(tok):
        return ('ref', tok), p + 1
    if tok.isalpha():
        return _parse_call(t, p)
    raise ValueError(f"unexpected token {tok!r}")


def _parse_call(t, p):
    name = t[p]
    p = _expect(t, p + 1, '(')
    if name == 'IF':
        left, p = _parse_expr(t, p)
        op = t[p]
        if op not in _OPS:
            raise ValueError(f"bad comparison {op!r}")
        right, p = _parse_expr(t, p + 1)
        p = _expect(t, p, ',')
        then, p = _parse_expr(t, p)
        p = _expect(t, p, ',')
        els, p = _parse_expr(t, p)
        p = _expect(t, p, ')')
        return ('if', left, op, right, then, els), p
    args = []
    while True:
        if p + 2 < len(t) and _is_cell(t[p]) and t[p + 1] == ':' and _is_cell(t[p + 2]):
            args.append(('range', t[p], t[p + 2]))
            p += 3
        else:
            node, p = _parse_expr(t, p)
            args.append(node)
        if p < len(t) and t[p] == ',':
            p += 1
            continue
        p = _expect(t, p, ')')
        break
    return ('func', name, args), p


def _range_names(c1, c2):
    r1, r2 = sorted((int(c1[1:]), int(c2[1:])))
    k1, k2 = sorted((c1[0], c2[0]))
    for r in range(r1, r2 + 1):
        for k in range(ord(k1), ord(k2) + 1):
            yield f"{chr(k)}{r}"


def _solve(cells):
    memo = {}
    busy = set()

    def cell_value(name):
        if name in memo:
            return memo[name]
        if name in busy:
            return _CYCLE
        if name not in cells:
            return 0
        busy.add(name)
        text = cells[name].strip()
        if text.startswith('='):
            tokens = _tokenize(text[1:])
            node, p = _parse_expr(tokens, 0)
            if p != len(tokens):
                raise ValueError(f"trailing tokens in {text!r}")
            value = ev(node)
        else:
            value = int(text)
        busy.discard(name)
        memo[name] = value
        return value

    def ev(node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return cell_value(node[1])
        if kind == 'neg':
            v = ev(node[1])
            return v if _is_err(v) else -v
        if kind == 'bin':
            left = ev(node[2])
            if _is_err(left):
                return left
            right = ev(node[3])
            if _is_err(right):
                return right
            op = node[1]
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            if op == '*':
                return left * right
            if right == 0:
                return _DIV0
            q = abs(left) // abs(right)
            return q if (left < 0) == (right < 0) else -q
        if kind == 'if':
            left = ev(node[1])
            if _is_err(left):
                return left
            right = ev(node[3])
            if _is_err(right):
                return right
            chosen = node[4] if _OPS[node[2]](left, right) else node[5]
            return ev(chosen)
        # kind == 'func'
        name = node[1]
        values = []
        for arg in node[2]:
            if arg[0] == 'range':
                for nm in _range_names(arg[1], arg[2]):
                    if nm in cells:
                        v = cell_value(nm)
                        if _is_err(v):
                            return v
                        values.append(v)
            else:
                v = ev(arg)
                if _is_err(v):
                    return v
                values.append(v)
        if name == 'SUM':
            return sum(values)
        if not values:
            return 0
        return min(values) if name == 'MIN' else max(values)

    return {name: cell_value(name) for name in cells}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Deep reference chains recurse through the evaluator, so run on a
    # thread with a large stack and a high recursion limit.
    box = {}

    def work():
        try:
            box['result'] = _solve(cells)
        except BaseException as exc:
            box['error'] = exc

    old_limit = sys.getrecursionlimit()
    old_stack = threading.stack_size()
    sys.setrecursionlimit(1_000_000)
    threading.stack_size(256 * 1024 * 1024)
    try:
        th = threading.Thread(target=work)
        th.start()
        th.join()
    finally:
        sys.setrecursionlimit(old_limit)
        threading.stack_size(old_stack)
    if 'error' in box:
        raise box['error']
    return box['result']
